(function(root){
const questions=[
{category:'Your emotional tone',title:'How pleasant does life feel right now?',hint:'Think about this moment, rather than how you think you should feel.',labels:['Very unpleasant','Somewhat unpleasant','Somewhere in between','Somewhat pleasant','Very pleasant'],signal:['Things feel unpleasant right now.','Things feel pleasant right now.']},
{category:'Your energy',title:'How much energy do you have?',hint:'Notice your pace, your body and your capacity to do things.',labels:['Almost no energy','A little energy','A steady amount','Quite a lot','A great deal of energy'],signal:['Your energy feels low.','Your energy feels high.']},
{category:'Your inner pace',title:'How tense or on edge do you feel?',hint:'Notice whether your thoughts or body feel settled or restless.',signal:['You feel relatively settled.','You feel tense or on edge.']},
{category:'Your connections',title:'How connected do you feel to other people?',hint:'Think about feeling understood or close to someone, even from a distance.',signal:['Connection with others feels distant.','You feel connected to other people.']},
{category:'Your sense of direction',title:'How much are you questioning your purpose or place in life?',hint:'This might mean wondering who you are, what matters or where you are heading.',signal:['Questions about purpose are not prominent.','Questions about purpose or identity are prominent.']},
{category:'What you miss',title:'How much are you missing someone or something?',hint:'It could be a person, a place, a possibility or an earlier chapter of life.',signal:['Missing something is not prominent.','Missing someone or something stands out.']},
{category:'Your relationship with yourself',title:'How strongly are you judging yourself?',hint:'Notice regret, self-doubt or the sense that you have fallen short.',signal:['Self-judgment is relatively quiet.','Self-judgment is weighing on you.']},
{category:'Your boundaries',title:'How frustrated or wronged do you feel?',hint:'Think about obstacles, unfairness or a boundary that has been crossed.',signal:['Frustration is relatively quiet.','Frustration or unfairness stands out.']},
{category:'Your emotional layers',title:'How much do pleasant and painful feelings coexist?',hint:'For example, feeling grateful and sad about the same experience.',signal:['Your feelings have a more consistent tone.','Pleasant and painful feelings are mixed together.']},
{category:'What lies ahead',title:'How uncertain does the near future feel?',hint:'Focus on how unclear things feel, whether that uncertainty is welcome or difficult.',signal:['The near future feels relatively clear.','The near future feels uncertain.']}
];
const profiles=[
['Happiness','A sense of enjoyment, warmth or satisfaction with life as it is right now.','Happiness does not have to be intense. It can be a quiet pleasure or a moment when things feel good enough.',[4,3,0,3,0,0,0,0,0,1]],
['Contentment','A quiet sense of enough: feeling settled without needing this moment to be different.','Contentment is usually gentler than excitement. It can show up as ease, steadiness and a little room to breathe.',[4,2,0,3,0,0,0,0,0,0]],
['Excitement','An energised, pleasant sense that something interesting is happening or on its way.','Excitement can include some nervousness. High energy and anticipation may be part of what gives the feeling its intensity.',[4,4,2,3,0,0,0,0,0,3]],
['Gratitude','A warm awareness of something or someone you value.','Gratitude can coexist with difficulty. Feeling connected and noticing what matters may fit this description; these questions do not directly ask what you appreciate.',[4,2,0,4,1,1,0,0,2,1]],
['Hopefulness','A sense of possibility, even while the next chapter is not fully clear.','Hopefulness leaves room for difficulty alongside the feeling that something good may still be possible.',[3,3,1,2,2,0,1,0,2,3]],
['Sadness','An emotional heaviness that can make life feel less bright or leave you with less energy.','Sadness may accompany disappointment, disconnection or change. This description names a feeling; it does not establish its cause or duration.',[0,1,1,2,1,2,2,0,1,2]],
['Loneliness','A painful gap between the connection you have and the connection you want.','Loneliness can happen with or without other people nearby. Feeling distant or not understood may be a central part of the experience.',[1,1,1,0,2,2,2,0,1,2]],
['Grief-like longing','A painful sense of missing someone, something or a life that has changed.','This may resemble grief if a loss is part of your situation. The questionnaire cannot establish that a loss occurred; longing can also concern an unrealised possibility.',[0,1,2,1,2,4,1,1,2,3]],
['Anxiety-like unease','An unsettled feeling of tension and uncertainty about what may happen next.','Your attention may be pulled towards the future. This describes an emotional pattern, not an anxiety disorder.',[1,3,4,2,1,0,2,1,1,4]],
['Overwhelm','A sense that there is more to take in or deal with than you have space for right now.','Tension alongside limited energy may fit this experience. Your answers cannot tell us whether demands, emotions or something else are behind it.',[1,1,4,1,2,1,3,3,2,4]],
['Frustration','An agitated feeling that something important is blocked, unfair or outside your control.','Frustration often has energy behind it. It may help name the distance between what you need and what is happening.',[1,3,3,2,1,0,1,4,0,2]],
['Self-directed disappointment','A painful sense of having fallen short of your own expectations.','Strong self-judgment can colour how a moment feels. This match does not mean that those judgments are fair or that you have actually failed.',[1,1,2,2,1,1,4,1,1,2]],
['Emotional depletion','A low-energy, unpleasant state with little room left for emotional demands.','This may feel flat or worn down. The questionnaire cannot identify a cause, and this label is not a diagnosis of burnout or depression.',[1,0,1,1,2,1,2,1,1,2]],
['Bittersweetness','Pleasure and pain sharing the same space: something can feel meaningful and difficult at once.','You may be appreciating what you have while missing what has changed. Neither side cancels the other out.',[2,2,1,3,1,3,1,0,4,2]],
['Existential unease','An unsettled sense of questioning who you are, what matters or where your life is going.','When intense, this experience is sometimes called an existential crisis. It is a broader experience rather than a single emotion; this check-in cannot establish that you are in a crisis.',[1,1,3,1,4,1,2,1,3,4]],
['Reflective uncertainty','An inward-looking state in which important questions are open and your feelings are still taking shape.','You may be exploring your direction without a single dominant emotion. Uncertainty does not have to mean that something is wrong.',[2,2,1,2,3,1,1,0,3,3]]
].map(([name,description,meaning,vector])=>({name,description,meaning,vector}));
const weights=[1.6,.9,1.2,1.1,1.4,1.3,1.1,1.1,1.2,.8];
function rank(answers){if(!Array.isArray(answers)||answers.length!==10||answers.some(a=>!Number.isInteger(a)||a<0||a>4))throw new Error('Please answer all ten questions with a value from 0 to 4.');return profiles.map(p=>({...p,distance:p.vector.reduce((s,v,i)=>s+weights[i]*(v-answers[i])**2,0)/weights.reduce((a,b)=>a+b,0)})).sort((a,b)=>a.distance-b.distance);}
function explain(answers,profile){return questions.map((q,i)=>({text:q.signal[answers[i]>=2?1:0],strength:Math.abs(answers[i]-2)*weights[i]/(1+Math.abs(answers[i]-profile.vector[i]))})).filter(x=>x.strength>.5).sort((a,b)=>b.strength-a.strength).slice(0,3).map(x=>x.text);}
root.EmotionModel={questions,profiles,rank,explain};
})(typeof module==='object'?module.exports:window);
